import {texEq as eq,inlineMath} from './math.js';
import {section,table,cite,topic,mountTopic,rangePlayback} from './topic-tools.js';
import {chainFrame,curvatureFrame} from './calculus-model.js';
export const calculusSections=[['local-change','Local change before optimizer choice'],['partial','Partial derivatives and coordinate slices'],['product','Products add two paths of change'],['chain','Compositions multiply local rates'],['backprop-lab','Forward values, backward accumulation'],['jacobian','Jacobians and vector–Jacobian products'],['autodiff','Automatic differentiation and checks'],['direction','Steepest direction depends on the norm'],['updates','A descent direction is not a safe finite step'],['hessian','Curvature classifies stationary points'],['curvature-lab','Rotate a slice through a critical point'],['index','Index and coordinate invariance'],['random','High dimension is not a landscape model'],['goe','What the GOE result actually says'],['kac-rice','Counting points requires conditional weighting'],['morse','Morse theory organizes the local geometry'],['practice','Translate geometry into training diagnostics'],['sources','Sources and related owners']];
export const calculusMeta={slug:'math/calculus',title:'Differentiation and Optimization Geometry',description:'Partial, product and chain rules become accumulated backpropagation; gradients, curvature, stationary points and random-landscape assumptions answer different questions.',date:'2026-04-08',updated:'2026-10-14',topicPath:['math'],tags:['calculus','gradient','chain rule','backpropagation','Hessian','Morse','Kac-Rice','GOE','saddle'],prototype:true,visibility:'public',kind:'dense-topic',learningGoals:['Accumulate all paths in reverse differentiation','Separate local steepness from finite-step stability','Interpret Hessian signatures without universal landscape claims'],related:['training/objectives','math/geometry']};
export const calculusAliases=[];
const graphNames=['x','a=x²','b=sin(a)','c=exp(b)','L=c'];
const backpropLab=`<div id="backprop-lab" class="topic-scene" data-backprop-lab><h3>Values go forward; sensitivities come back</h3><p>The same scalar graph can have one chain or an added edge a→L. An adjoint is ∂L/∂node. All incoming backward contributions must be added.</p><label>Output expression<select aria-label="Graph output expression"><option value="chain">L=c</option><option value="skip">L=c+a</option></select></label><label>Input x <output data-input-x>0.50</output><input type="range" min="0" max="100" value="50" aria-label="Graph input in hundredths"></label><label>Execution step <output data-graph-step>8</output> / 8<input type="range" min="0" max="8" step="1" value="8" aria-label="Forward backward step"></label><div class="calculus-graph">${chainFrame().values.map((v,i)=>`<div data-graph-node="${i}"><b data-node-name>${graphNames[i]}</b><span>value <output data-node-value>${v.toFixed(4)}</output></span><span>adjoint <output data-node-adjoint>${chainFrame().adjoints[i].toFixed(4)}</output></span></div>`).join('')}</div><p data-extra-edge>No extra edge: only c contributes to L.</p><p data-graph-caption>Backward: a=x² sends 2x times a's total adjoint to x. ${inlineMath(String.raw`\frac{\partial L}{\partial x}=1.2409`)}.</p><div class="dense-actions"><button data-play type="button">Play</button><button data-reset type="button">Replay</button></div><p class="topic-scenes-caption">Exact scalar illustration, not a trained network. Playback follows operation order; x and output expression remain fixed. Zero adjoints before their propagation mean not yet accumulated, not necessarily a final zero derivative.</p></div>`;
function sliceSvg(kind,angle){const pts=Array.from({length:81},(_,i)=>{const r=-1+i/40,f=curvatureFrame(kind,angle,r);return `${50+(r+1)*200},${160-70*f.value}`;});return `<path d="M30 160H470 M250 15V305" stroke="#806278"/><path d="M${pts.join(' L')}" fill="none" stroke="#bad6fa" stroke-width="4"/><circle cx="250" cy="160" r="5" fill="#bd738e"/>`;}
const curvatureLab=`<div id="curvature-lab" class="topic-scene" data-curvature-lab><h3>One point, several possible directions</h3><p>Every example is stationary at the origin. Horizontal axis: displacement r from −1 to 1. Vertical axis: Δf on a fixed scale, with the zero line through the burgundy origin.</p><label>Landscape<select aria-label="Curvature landscape"><option value="saddle">½(x²−y²): saddle</option><option value="minimum">½(x²+3y²): minimum</option><option value="maximum">−½(x²+3y²): maximum</option><option value="quartic">x⁴+y⁴: degenerate minimum</option></select></label><label>Slice direction <output data-direction-angle>90</output>°<input type="range" min="0" max="180" step="1" value="90" aria-label="Curvature slice angle"></label><svg viewBox="0 0 500 320" role="img" aria-label="Exact function slice through a stationary origin">${sliceSvg('saddle',90)}</svg><div class="scene-stats"><span>Hessian eigenvalues <output data-eigenvalues>1, −1</output></span><span>${inlineMath(String.raw`d^\top Hd`)} <output data-direction-curvature>−1.000</output></span><span>Δf at r=1 <output data-slice-change>−0.500</output></span></div><p data-curvature-caption>Negative curvature: moving away from zero along this slice lowers f.</p><div class="dense-actions"><button data-play type="button">Play</button><button data-reset type="button">Replay</button></div><p class="topic-scenes-caption">Exact toy functions. Angle sweeps are not optimizer trajectories. A flat quadratic slice in the saddle does not make the entire Hessian zero.</p></div>`;
export function calculusReader(link){return topic(calculusMeta,calculusSections,'Compute the sensitivity; then ask what the local geometry permits.',`
<p>A training loss depends on many intermediate quantities and parameters. Differentiation tells us how a small change propagates through those computations. Optimization then chooses a finite update. These are connected operations, not the same question.</p><p>Start with coordinate slices and local rules. Combine them into a graph, add every backward path, and interpret the resulting gradient. Only then use curvature to distinguish steepness, stationary points and possible escape directions.</p>
${section('local-change','Local change before optimizer choice',`${eq(String.raw`f(x+h)=f(x)+\nabla f(x)^\top h+o(\lVert h\rVert)`,'For a differentiable scalar function, the gradient supplies the first-order linear change.')}
<p>A derivative is local. A negative first-order prediction does not prove that a large update lowers the loss. Curvature, nonsmooth boundaries and changes in the data can invalidate a distant extrapolation.</p><p>Differentiability is stronger than having some coordinate derivatives. The gradient-based linear approximation needs the appropriate regularity. ReLU boundaries and other nonsmooth points require an explicit derivative/subgradient convention.</p>`)}
${section('partial','Partial derivatives and coordinate slices',`${eq(String.raw`\begin{aligned}\partial_x f(x,y)&=\lim_{h\to0}\frac{f(x+h,y)-f(x,y)}h\\\partial_y f(x,y)&=\lim_{h\to0}\frac{f(x,y+h)-f(x,y)}h\end{aligned}`,'Hold the other coordinate fixed. Equivalent notations include ∂ₓf, fₓ and Dₓf.')}
<p>For ${inlineMath(String.raw`f(x,y)=x^2y+xy^2`)}, ${inlineMath(String.raw`\partial_xf=2xy+y^2`)} and ${inlineMath(String.raw`\partial_yf=x^2+2xy`)}. At (2,3), f=30 and ${inlineMath(String.raw`\nabla f=[21,16]`)}. The two partials are the slopes of the surface's coordinate slices.</p><p>If y itself depends on x, the total derivative also includes the path through y: ${inlineMath(String.raw`\frac{df}{dx}=\partial_xf+\partial_yf\,\frac{dy}{dx}`)}. Holding y fixed and moving along a curve are different experiments.</p><p>For ${inlineMath(String.raw`L(w,b)=\frac1n\sum_i(wx_i+b-y_i)^2`)}, the two parameter sensitivities are ${inlineMath(String.raw`\partial_wL=\frac2n\sum_i(wx_i+b-y_i)x_i`)} and ${inlineMath(String.raw`\partial_bL=\frac2n\sum_i(wx_i+b-y_i)`)}. Plain gradient descent computes both at the same old (w,b), then updates them together.</p>`)}
${section('product','Products add two paths of change',`${eq(String.raw`\frac{d}{dx}[f(x)g(x)]=\frac{df}{dx}g(x)+f(x)\frac{dg}{dx}`,'Leibniz notation names the input variable. The primed form below expresses the same identity.')}${eq(String.raw`\begin{aligned}(fg)'&=f'g+fg'\\(uvw)'&=u'vw+uv'w+uvw'\end{aligned}`,'Differentiate one factor at a time, keeping the remaining factors unchanged in that term.')}
<p>Think of a rectangle with sides f and g. Its area change is gΔf+fΔg+ΔfΔg. The small corner is second order in the input change, so it disappears after division by the step and a limit.</p><p>For x²sin(x), the derivative is ${inlineMath(String.raw`2x\sin(x)+x^2\cos(x)`)}. The two terms arise because x reaches the product through two factors. A graph's repeated input therefore needs the sum of both backward contributions.</p>`)}
${section('chain','Compositions multiply local rates',`${eq(String.raw`\begin{aligned}(f\circ g)'(x)&=f'(g(x))g'(x)\\\frac{dy}{dx}&=\frac{dy}{dv}\frac{dv}{du}\frac{du}{dx}\end{aligned}`,'Evaluate each local derivative at its own forward value. Leibniz notation suggests cancellation, but the chain rule is not division of arbitrary symbols.')}
<p>If temperature changes by 2°C/hour and a sensor changes by .5 units/°C, its reading changes by 1 unit/hour. Multiplying the rates both propagates sensitivity and checks units.</p><p>For ${inlineMath(String.raw`h(x)=\exp(\sin(x^2))`)} at x=.5: a=.25, b=sin(a)=.247404, h=exp(b)=1.280696. The local rates are 2x=1, cos(a)=.968912 and exp(b)=1.280696. Their product is 1.240883.</p><p>A deep model composes vector operations, not only scalar functions. The same rule applies, with Jacobians and sums over intermediate coordinates. Associativity permits efficient grouping; matrix multiplication generally does not commute.</p>${backpropLab}`)}
${section('jacobian','Jacobians and vector–Jacobian products',`${eq(String.raw`\begin{aligned}J_f&\in\mathbb R^{m\times n},\quad(J_f)_{ij}=\frac{\partial f_i}{\partial x_j}\\\nabla_x(L\circ f)&=J_f^\top\nabla_f L\end{aligned}`,'Column-gradient convention: n inputs, m outputs. Reverse mode applies a vector–Jacobian product without materializing the full matrix.')}
<p>At a scalar node v, its adjoint is ${inlineMath(String.raw`\bar v=\frac{\partial L}{\partial v}`)}. Reverse traversal applies ${inlineMath(String.raw`\bar u\mathrel{+}=\bar v\,\frac{\partial v}{\partial u}`)} for each parent u. The += matters when several children depend on the same u.</p>${eq(String.raw`\begin{aligned}L&=\exp(\sin a)+a,\quad a=x^2\\\bar a&=\exp(\sin a)\cos a+1\\\bar x&=2x\bar a\end{aligned}`,'At x=.5, the chain contributes 1.240883 and the direct a→L edge contributes 1. The total is 2.240883.')}
<p>For a scalar loss with many parameters, reverse mode computes all parameter gradients in one backward traversal. Forward mode instead pushes an input-direction tangent through the graph, producing Jv. Choose the mode by input/output dimension and the requested derivative product.</p><p>Reverse mode needs forward values for local derivatives. Saving them costs memory; recomputation trades compute for storage. These choices affect execution, not the derivative identity.</p>`)}
${section('autodiff','Automatic differentiation and checks',`<p>Automatic differentiation evaluates local derivative rules on the executed program. It is neither symbolic simplification of the whole function nor a finite-difference approximation, although floating-point arithmetic still introduces rounding.</p><p>A small PyTorch reference computes the chain derivative. This snippet is illustrative; the pure numerical model is tested separately.</p><pre><code>import torch
x = torch.tensor(0.5, dtype=torch.float64, requires_grad=True)
a = x.square()
h = a.sin().exp()
h.backward()
# x.grad is approximately 1.2408826092</code></pre><p>${cite('https://docs.pytorch.org/docs/main/generated/torch.autograd.backward.html','PyTorch backward')} accumulates leaf gradients. Reset or intentionally accumulate them between passes. A nonscalar output needs an output seed of matching shape; summing outputs is one particular scalar objective, not a neutral substitute.</p><p>A numerical check uses ${inlineMath(String.raw`\frac{f(x+\varepsilon)-f(x-\varepsilon)}{2\varepsilon}`)}. Compare several step sizes in high precision away from nonsmooth points. Large ε has truncation error; very small ε has cancellation. For vectors, a directional check compares that quotient along d with ${inlineMath(String.raw`\nabla f\cdot d`)}.</p><p>Detached tensors, in-place modification of saved values, ignored branches or custom backward rules can change what the program differentiates. A plausible loss curve is not a derivative correctness test.</p>`)}
${section('direction','Steepest direction depends on the norm',`<p>The gradient collects the coordinate sensitivities into one column vector. Its Euclidean norm combines those components into a length.</p>${eq(String.raw`\begin{aligned}\nabla f(x)&=\left[\frac{\partial f}{\partial x_1},\ldots,\frac{\partial f}{\partial x_n}\right]^\top\\\lVert\nabla f(x)\rVert_2&=\sqrt{\sum_{i=1}^n\left(\frac{\partial f}{\partial x_i}\right)^2}\end{aligned}`,'These definitions need differentiability for the first-order directional interpretation. A coordinate gradient is not a coordinate-invariant measure of sensitivity.')}${eq(String.raw`\begin{aligned}D_df&=\nabla f\cdot d\le\lVert\nabla f\rVert_2\lVert d\rVert_2\\d_{\mathrm{ascent}}&=\frac{\nabla f}{\lVert\nabla f\rVert_2},\quad\lVert d\rVert_2=1,\ \nabla f\ne0\end{aligned}`,'Cauchy–Schwarz identifies the steepest first-order ascent under a Euclidean unit-step constraint.')}
<p>Negative normalized gradient gives Euclidean steepest descent. A different norm, metric or parameter scaling can give a different steepest direction. This distinction matters when comparing preconditioned updates.</p><p>For ${inlineMath(String.raw`\nabla f=[3,4]`)}, the norm is 5, unit ascent is [.6,.8] and unit descent is [−.6,−.8]. The norm is the largest directional derivative among Euclidean unit directions, not a promise that every small displacement changes f by that amount.</p><p>At zero gradient there is no unique steepest first-order direction. The zero vector is the gradient, not a defined unit direction. Momentum, stochasticity or higher-order structure can still produce movement; not every optimizer automatically stops.</p>`)}
${section('updates','A descent direction is not a safe finite step',`${eq(String.raw`\begin{aligned}\theta_{t+1}&=\theta_t-\eta g_t\\\lVert\Delta\theta\rVert_2&=\eta\lVert g_t\rVert_2,\quad\eta\ge0\end{aligned}`,'For plain gradient descent. Adaptive scaling, momentum and clipping modify the actual update.')}
<p>A large gradient with a large learning rate can overshoot. Small gradient norm can mean a useful stationary region, bad scaling, cancellation or a plateau. It does not distinguish these cases on its own.</p><p>For ${inlineMath(String.raw`f(x)=\frac12\lambda x^2`)} with λ&gt;0, the update is ${inlineMath(String.raw`x'=(1-\eta\lambda)x`)}. This scalar quadratic converges when ${inlineMath(String.raw`0<\eta<\frac2\lambda`)}. At the upper boundary it oscillates without reducing magnitude; above it, magnitude grows. Gradient direction is unchanged, but finite-step stability is not.</p>${eq(String.raw`g_{\mathrm{clip}}=\begin{cases}g,&\lVert g\rVert_2\le\tau\\\dfrac{\tau}{\lVert g\rVert_2}g,&\lVert g\rVert_2>\tau\end{cases},\quad\tau>0`,'At zero g, retain zero without dividing. This clips gradient norm, not necessarily the final preconditioned update.')}
<p>Clipping preserves a nonzero gradient's direction while reducing its magnitude. It can prevent a large update, but it does not correct NaNs, a wrong derivative or an unsuitable objective. <a href="${link('training/optimization')+'#clipping'}">Gradient Clipping reference →</a> retains the training-specific implementation conditions.</p>`)}
${section('hessian','Curvature classifies stationary points',`${eq(String.raw`\begin{aligned}H_{ij}&=\frac{\partial^2f}{\partial x_i\partial x_j}\\f(x+h)&=f(x)+\nabla f(x)^\top h\\&\quad+\tfrac12h^\top Hh+o(\lVert h\rVert^2)\end{aligned}`,'For a C² function, continuous mixed second partials commute, so H is symmetric.')}
<p>At an interior stationary point, ${inlineMath(String.raw`\nabla f=0`)} removes the linear Taylor term. The Hessian gives the quadratic term, which can vanish in some or all directions. Diagonalize the symmetric Hessian: ${inlineMath(String.raw`h^\top Hh=\sum_i\lambda_i a_i^2`)} in an orthonormal eigenbasis.</p>${table('Second-order classification at a stationary point',['Hessian signature','Conclusion'],[['All eigenvalues positive','Strict local minimum'],['All negative','Strict local maximum'],['Positive and negative','Saddle'],['Some zero, no definitive mixed-sign test','Higher-order analysis may be needed']])}<p>Positive curvature away from a stationary point does not mean the current point is a minimum. Positive semidefinite curvature at a stationary point is necessary for a smooth local minimum, but it is not sufficient. x⁴ has a strict minimum with zero second derivative; −x⁴ has a maximum with the same zero second derivative.</p><p>One negative eigenvalue rules out a smooth local minimum. To call a nondegenerate critical point a saddle rather than a maximum, it must also have positive curvature. A constrained boundary requires a different stationarity and feasible-direction analysis.</p>${curvatureLab}`)}
${section('index','Index and coordinate invariance',`${eq(String.raw`\operatorname{index}(H)=\#\{i:\lambda_i<0\}`,'At a nondegenerate critical point: index 0 is a minimum, N a maximum, and intermediate indices are saddles.')}
<p>For f(x,y)=xy, the Hessian is [[0,1],[1,0]]. Both coordinate-axis curvatures are zero, yet its eigenvalues are ±1. With ${inlineMath(String.raw`u=\frac{x+y}{\sqrt2}`)} and ${inlineMath(String.raw`v=\frac{x-y}{\sqrt2}`)}, ${inlineMath(String.raw`f=\frac{u^2-v^2}{2}`)}. Mixed terms can hide an escape direction.</p><p>An invertible linear coordinate change preserves the positive/negative/zero counts of a quadratic form. Eigenvalue magnitudes need not remain the same under arbitrary scaling. At a stationary point, smooth local coordinate changes preserve this signature; away from stationarity, extra Hessian transformation terms matter.</p>`)}
${section('random','High dimension is not a landscape model',`<p>Two different claims must stay separate: critical points occupy little ambient volume, and minima are uncommon among critical points. For a Morse function, nondegenerate critical points are isolated. This volume-zero fact already appears in one dimension; it does not establish saddle dominance.</p><p>The second question needs a sampling model over functions or critical points. Merely writing ${inlineMath(String.raw`P(\mathrm{minimum}\mid\nabla f=0)`)} does not specify it. Gradient-zero events can have probability zero at a fixed random location, so a conditional density or point-counting construction is needed.</p>${eq(String.raw`P(\lambda_1>0,\ldots,\lambda_N>0)=2^{-N}`,'Independent, unbiased eigenvalue-sign toy. This is an intuition, not a random-matrix law. Real symmetric-matrix eigenvalues are correlated.')}
<p>A minimum requires every curvature direction to be nonnegative, and every eigenvalue positive in the nondegenerate case. Mixed signs supply both up and down directions. But dimension alone determines neither sign distribution nor optimizer behavior.</p><p>For example, ${inlineMath(String.raw`f(x)=\|x\|_2^2`)} has exactly one critical point, its global minimum, in any dimension. It has no saddles. This strongly convex example rules out a universal dimension-only claim.</p>`)}
${section('goe','What the GOE result actually says',`<p>The Gaussian Orthogonal Ensemble (GOE) models a centered real symmetric random matrix with Gaussian entries and an appropriate normalization. Its limiting eigenvalue density is symmetric around zero, so a large centered matrix usually has many eigenvalues of each sign.</p>${eq(String.raw`P(H_N\succ0)=\exp\{-cN^2+o(N^2)\},\quad c>0`,'An asymptotic positive-definiteness event for centered GOE matrices, not the probability that a trained network reaches a bad minimum.')}
<p>${cite('https://arxiv.org/abs/cond-mat/0609651','Dean and Majumdar')} report the Gaussian-ensemble N² exponent. It describes a specified matrix ensemble. A landscape Hessian can correlate with the loss value and gradient; conditioning on a low value can shift its spectrum upward.</p><p>Do not turn a vanishing fraction into zero absolute count. A landscape can have increasingly many minima while saddles grow faster. Nor does uniformly counting critical points match how an optimizer visits their attraction regions.</p>`)}
${section('kac-rice','Counting points requires conditional weighting',`${eq(String.raw`\begin{aligned}C_k(D)&=\#\{x\in D:\nabla f(x)=0,\ \operatorname{index}H(x)=k\}\\\mathbb E[C_k(D)]&=\int_D\mathbb E\bigl[|\det H(x)|\,\mathbf1\{\operatorname{index}H(x)=k\}\\&\hspace{5em}\mid\nabla f(x)=0\bigr]\,p_{\nabla f(x)}(0)\,dx\end{aligned}`,'Kac–Rice under suitable random-field regularity/nondegeneracy assumptions. '+inlineMath(String.raw`p_{\nabla f(x)}(0)`)+' is a density, not the mass of an exact zero event.')}
<p>The gradient density locates candidate zeros; the determinant weights their local Jacobian volume change; the indicator selects an index. Counting minima sets k=0, while nondegenerate saddles sum k=1 through N−1.</p><p>This determinant-weighted conditional expectation explains why sampling an unconditional GOE matrix is not the same as sampling a typical landscape critical point. Gaussian field and spin-glass calculations can use random-matrix tools, but their conditioning and energy regimes remain part of the result.</p>`)}
${section('morse','Morse theory organizes the local geometry',`<p>A Morse function has nondegenerate critical points. The Hessian's invertibility isolates such a gradient zero locally. This is a structural statement, not a probability estimate.</p><p>The Morse lemma gives local coordinates with k negative squares and N−k positive squares at an index-k point. It explains why index is the invariant. It does not by itself prove that saddles outnumber minima.</p><p>The linked landscape article also connects index to topology as a level set crosses a critical value. That reference is useful for the topological extension; the optimization argument here remains conditional on the landscape model.</p>`)}
${section('practice','Translate geometry into training diagnostics',`<p>Real neural losses have parameter symmetries, degenerate directions, structured data and nonsmooth operations. A random-Hessian model can provide intuition without being an empirical diagnosis of a particular run.</p>${table('Observed signal is not a diagnosis',['Signal','What it can support','What else to inspect'],[['Small gradient norm','Small local first-order change in this metric','Loss scaling, clipping, update norms, curvature'],['Large norm','Large possible Euclidean directional rate','Batch reduction, outliers, step size, numerical errors'],['Negative Hessian direction','A local escape direction at stationarity','Magnitude, feasible directions, optimizer noise'],['Near-zero eigenvalues','Weak quadratic curvature','Higher orders, symmetry and parameterization'],['Training loss decreases','The chosen objective improved on these batches','Validation, generalization and actual update behavior']])}<p>Separate full-objective gradients from minibatch estimates. Stochastic gradients need not shrink to zero near a population optimum. Per-parameter rescaling can also change gradient norm without changing the represented function.</p><p><a href="${link('training/optimization')+'#gradient-diagnostics'}">Gradient-norm training reference →</a> and <a href="${link('training/optimization')+'#batch-design'}">batch/LR reference →</a> own run-specific scaling and update choices. <a href="${link('training/objectives')}">Losses and Objectives →</a> defines what those derivatives measure.</p>`)}
${section('sources','Sources and related owners',`<p>${cite('https://www.grantstenger.com/local-minima','Hessians, random landscapes and Morse points')} · ${cite('https://arxiv.org/abs/cond-mat/0609651','Gaussian-matrix large deviations')} · ${cite('https://docs.pytorch.org/docs/main/generated/torch.autograd.backward.html','Autograd backward')}</p><div class="dense-related"><a href="${link('training/objectives')}">Losses and Objectives →</a><a href="${link('math/geometry')}">Norms and vector geometry →</a></div>`)}
`);}
calculusMeta.searchText=calculusReader(()=> '').replace(/<[^>]*>/g,' ');
export function mountCalculus(scope=document){mountTopic(scope,calculusMeta.slug,article=>{
 const graph=article.querySelector('[data-backprop-lab]'),sliders=graph.querySelectorAll('input[type="range"]'),x=sliders[0],step=sliders[1],output=graph.querySelector('select');
 const stages=['Input x is available.','Forward: a=x². Save x for its local derivative.','Forward: b=sin(a). Save a.','Forward: c=exp(b). Save c.','Forward: compute L and seed its adjoint with 1.','Backward: L sends 1 to c, and to a if the extra edge exists.','Backward: c sends c times its adjoint to b.','Backward: b sends cos(a) times its adjoint to a. Add the earlier direct contribution.','Backward: a sends 2x times its total adjoint to x.'];
 const control=rangePlayback(article,graph,s=>{const f=chainFrame(Number(x.value)/100,output.value==='skip',s);graph.querySelector('[data-input-x]').textContent=(Number(x.value)/100).toFixed(2);graph.querySelector('[data-graph-step]').textContent=s;graph.querySelectorAll('[data-graph-node]').forEach((node,i)=>{node.querySelector('[data-node-name]').textContent=i===4?(f.skip?'L=c+a':'L=c'):graphNames[i];node.querySelector('[data-node-value]').textContent=f.ready[i]?f.values[i].toFixed(4):'—';node.querySelector('[data-node-adjoint]').textContent=f.adjoints[i].toFixed(4);node.classList.toggle('calculus-ready',f.ready[i]);});graph.querySelector('[data-extra-edge]').textContent=f.skip?'Additional edge a→L contributes +1 to a’s adjoint at step 5. Its contribution is retained when the chain arrives.':'No extra edge: only c contributes to L.';graph.querySelector('[data-graph-caption]').innerHTML=stages[s]+(s===8?` ${inlineMath(String.raw`\frac{\partial L}{\partial x}=${f.derivative.toFixed(6)}`)}.`:'');},16000,step);for(const input of [x,output])input.addEventListener(input===output?'change':'input',()=>{control.stop();control.render();});
 const lab=article.querySelector('[data-curvature-lab]'),kind=lab.querySelector('select'),curvature=rangePlayback(article,lab,angle=>{const f=curvatureFrame(kind.value,angle);lab.querySelector('[data-direction-angle]').textContent=angle;lab.querySelector('svg').innerHTML=sliceSvg(kind.value,angle);lab.querySelector('[data-eigenvalues]').textContent=f.eigen.join(', ');lab.querySelector('[data-direction-curvature]').textContent=f.k.toFixed(3);lab.querySelector('[data-slice-change]').textContent=f.value.toFixed(3);lab.querySelector('[data-curvature-caption]').textContent=kind.value==='quartic'?'Zero Hessian, yet every nonzero slice rises by a fourth-order term. This origin is a strict, degenerate minimum.':Math.abs(f.k)<1e-10?'This quadratic slice is flat; other directions can still have curvature.':f.k<0?'Negative curvature: moving away from zero along this slice lowers f.':'Positive curvature: moving away from zero along this slice raises f.';},16000);kind.addEventListener('change',()=>{curvature.stop();curvature.render();});
});}
